spec fn prefix_in_range(a: &[i64], lo: i64, hi: i64, n: usize) -> bool {
    forall|k: usize| k < n && k < a.len() ==> lo <= #[trigger] a[k] && a[k] <= hi
}

spec fn all_in_range_spec(a: &[i64], lo: i64, hi: i64, r: bool) -> bool {
    r == (forall|k: usize| k < a.len() ==> lo <= #[trigger] a[k] && a[k] <= hi)
}

spec fn loop_inv(a: &[i64], lo: i64, hi: i64, i: usize, ok: bool) -> bool {
    i <= a.len() && ok == (forall|k: usize| k < i ==> lo <= #[trigger] a[k] && a[k] <= hi)
}

#[effects(pure)]
#[uses(all_in_range_spec, loop_inv)]
fn all_in_range(a: &[i64], lo: i64, hi: i64) -> (r: bool)
    ensures all_in_range_spec(a, lo, hi, r),
{
    let mut i: usize = 0;
    let mut ok: bool = true;
    while i < a.len()
        invariant loop_inv(a, lo, hi, i, ok),
        decreases a.len() - i,
    {
        let x: i64 = a[i];
        ok = ok && lo <= x && x <= hi;
        i = i + 1;
    }
    ok
}

spec fn no_v_from(a: &[i64], v: i64, i: usize) -> bool {
    i <= a.len() && forall|j: usize| i <= j && j < a.len() ==> (#[trigger] a[j]) != v
}

spec fn is_last(a: &[i64], v: i64, r: usize) -> bool {
    r < a.len() && a[r] == v && forall|j: usize| r < j && j < a.len() ==> (#[trigger] a[j]) != v
}

spec fn none_is(a: &[i64], v: i64) -> bool {
    forall|j: usize| j < a.len() ==> (#[trigger] a[j]) != v
}

spec fn find_last_post(a: &[i64], v: i64, r: usize) -> bool {
    (r < a.len() && is_last(a, v, r)) || (r == a.len() && none_is(a, v))
}

#[effects(pure)]
#[uses(no_v_from, is_last, none_is, find_last_post)]
fn find_last(a: &[i64], v: i64) -> (r: usize)
    ensures find_last_post(a, v, r),
{
    let mut i: usize = a.len();
    while i > 0 && a[i - 1] != v
        invariant no_v_from(a, v, i),
        decreases i,
    {
        i = i - 1;
    }
    if i == 0 {
        a.len()
    } else {
        i - 1
    }
}

spec fn is_max3(a: i64, b: i64, c: i64, r: i64) -> bool {
    r >= a && r >= b && r >= c && (r == a || r == b || r == c)
}

#[effects(pure)]
#[uses(is_max3, num::is_max2)]
fn max3(a: i64, b: i64, c: i64) -> (r: i64)
    ensures is_max3(a, b, c, r),
{
    let m: i64 = num::max2(a, b);
    num::max2(m, c)
}

spec fn min_at(a: &[i64], r: usize) -> bool {
    r < a.len() && (forall|k: usize| k < a.len() ==> a[r] <= #[trigger] a[k])
}

#[effects(pure)]
