#[effects(pure)]
#[uses(small, added, progress, stats::bounded_elems)]
fn add_all(a: &mut [i64], d: i64) -> ()
    requires stats::bounded_elems(old(a)), small(d),
    ensures added(a, old(a), d),
{
    let n: usize = a.len();
    let mut i: usize = 0;
    while i < n
        invariant n == a.len(), progress(a, old(a), d, i), stats::bounded_elems(old(a)), small(d),
        decreases n - i,
    {
        a[i] = a[i] + d;
        i = i + 1;
    }
}

