spec fn digits_post(n: u64, r: u64) -> bool {
    r >= 1 && r <= n + 1 && ((r == 1) == (n < 10))
}

spec fn digits_inv(n: u64, m: u64, c: u64) -> bool {
    c >= 1 && c + m <= n + 1 && m <= n && (c == 1 ==> m == n) && (n < 10 ==> c == 1)
}

#[effects(pure)]
#[uses(digits_post, digits_inv)]
fn count_digits_iter(n: u64) -> (r: u64)
    ensures digits_post(n, r),
{
    let mut m: u64 = n;
    let mut c: u64 = 1;
    while m >= 10
        invariant digits_inv(n, m, c),
        decreases m,
    {
        m = m / 10;
        c = c + 1;
    }
    c
}

