#[effects(pure)]
#[uses(bounds_ok, all_in_range, in_range_kept, clamped_below)]
fn clamp_all(a: &mut [i64], lo: i64, hi: i64) -> ()
    requires bounds_ok(lo, hi),
    ensures all_in_range(a, lo, hi), in_range_kept(old(a), a, lo, hi),
{
    let mut k: usize = 0;
    while k < a.len()
        invariant clamped_below(old(a), a, lo, hi, k),
        decreases a.len() - k,
    {
        let v: i64 = a[k];
        if v < lo {
            a[k] = lo;
        } else if v > hi {
