#[effects(pure)]
#[uses(arr::nonempty, bounded_elems, in_thousand, num::is_max2, ge_first)]
fn max_of(a: &[i64]) -> (r: i64)
    requires arr::nonempty(a), bounded_elems(a),
    ensures in_thousand(r), ge_first(a, r),
{
    let mut m: i64 = a[0];
    let mut k: usize = 1;
    while k < a.len()
        invariant 1 <= k, k <= a.len(), in_thousand(m), a[0] <= m,
        decreases a.len() - k,
    {
        m = num::max2(m, a[k]);
        k = k + 1;
    }
    m
}

