spec fn is_abs_diff(a: i64, b: i64, r: i64) -> bool {
    r >= 0 && (r == a - b || r == b - a)
}

#[effects(pure)]
#[uses(is_abs_diff, small)]
fn abs_diff(a: i64, b: i64) -> (r: i64)
    requires small(a), small(b),
    ensures is_abs_diff(a, b, r),
{
    if a >= b {
        a - b
    } else {
        b - a
    }
}

spec fn elems_thousand(a: &[i64]) -> bool {
    forall|k: usize| k < a.len() ==> -1000 <= #[trigger] a[k] && a[k] <= 1000
}

spec fn gap_upto(a: &[i64], n: usize, r: i64) -> bool {
    forall|i: usize| i + 1 < n && i + 1 < a.len() ==> #[trigger] a[i] - a[i + 1] <= r && a[i + 1] - a[i] <= r
}

spec fn gap_ok(a: &[i64], r: i64) -> bool {
    r >= 0 && (forall|i: usize| i + 1 < a.len() ==> #[trigger] a[i] - a[i + 1] <= r && a[i + 1] - a[i] <= r)
}

#[effects(pure)]
#[uses(elems_thousand, gap_upto, gap_ok, num::small, num::is_abs_diff)]
fn max_gap(a: &[i64]) -> (r: i64)
    requires elems_thousand(a),
    ensures gap_ok(a, r),
{
    if a.len() == 0 {
        0
    } else {
        let mut m: i64 = 0;
        let mut k: usize = 1;
        while k < a.len()
            invariant 1 <= k, k <= a.len(), m >= 0, gap_upto(a, k, m), elems_thousand(a),
            decreases a.len() - k,
        {
            let d: i64 = num::abs_diff(a[k - 1], a[k]);
            if d > m {
                m = d;
            }
            k = k + 1;
        }
        m
    }
}

#[effects(pure)]
#[uses(ledger::acct, ledger::amount_ok, ledger::cap_ok, stats::at_most_len)]
fn deposit_all(a: &mut [i64], x: i64) -> (r: usize)
    requires ledger::cap_ok(a), ledger::amount_ok(x),
    ensures ledger::cap_ok(a), stats::at_most_len(a, r),
{
    let mut n: usize = 0;
    let mut k: usize = 0;
    while k < a.len()
        invariant k <= a.len(), n <= k, ledger::cap_ok(a), ledger::amount_ok(x),
        decreases a.len() - k,
    {
        if ledger::deposit(a, k, x) {
            n = n + 1;
        }
        k = k + 1;
    }
    n
}

spec fn same_len(a: &[i64], out: &[i64]) -> bool {
    out.len() == a.len()
}

spec fn first_ok(a: &[i64], out: &[i64]) -> bool {
    a.len() > 0 ==> out[0] == a[0]
}

spec fn steps_ok(a: &[i64], out: &[i64]) -> bool {
    forall|k: usize| k + 1 < a.len() ==> #[trigger] out[k + 1] == out[k] + a[k + 1]
}

#[effects(pure)]
#[uses(stats::bounded_elems, same_len, first_ok, steps_ok)]
fn prefix_sums(a: &[i64], out: &mut [i64]) -> ()
    requires stats::bounded_elems(a), same_len(a, old(out)),
    ensures same_len(a, out), first_ok(a, out), steps_ok(a, out),
{
    let mut s: i64 = 0;
    let mut i: usize = 0;
    while i < a.len()
        invariant
            i <= a.len(),
            out.len() == a.len(),
            -1000 * i <= s && s <= 1000 * i,
            i > 0 ==> out[i - 1] == s,
            i > 0 ==> out[0] == a[0],
            forall|k: usize| k + 1 < i ==> #[trigger] out[k + 1] == out[k] + a[k + 1],
        decreases a.len() - i,
    {
        s = s + a[i];
        out[i] = s;
        i = i + 1;
    }
}

