spec fn in_bounds(a: i64, b: i64) -> bool { -1000000000 <= a && a <= 1000000000 && 1 <= b && b <= 1000000000 }

spec fn is_floor_div(a: i64, b: i64, r: i64) -> bool { r * b <= a && a < r * b + b }

#[effects(pure)]
#[uses(in_bounds, is_floor_div)]
fn div_floor(a: i64, b: i64) -> (r: i64)
    requires in_bounds(a, b),
    ensures is_floor_div(a, b, r),
{
    let q: i64 = a / b;
    let m: i64 = a % b;
    if m < 0 { q - 1 } else { q }
}

spec fn is_one_of(r: i64, a: i64, b: i64, c: i64) -> bool { r == a || r == b || r == c }

spec fn is_between(r: i64, a: i64, b: i64, c: i64) -> bool {
    (r == a && ((b <= a && a <= c) || (c <= a && a <= b)))
    || (r == b && ((a <= b && b <= c) || (c <= b && b <= a)))
    || (r == c && ((a <= c && c <= b) || (b <= c && c <= a)))
}

#[effects(pure)]
#[uses(is_one_of, is_between)]
fn median3(a: i64, b: i64, c: i64) -> (r: i64)
    ensures is_one_of(r, a, b, c), is_between(r, a, b, c),
{
    if (b <= a && a <= c) || (c <= a && a <= b) {
        a
    } else if (a <= b && b <= c) || (c <= b && b <= a) {
        b
    } else {
        c
    }
}

